(\forall_N yA)[x:=u]=
\begin{cases}
\forall_N yA,&y=x,\\
\forall_N y(A[x:=u]),&y\ne x\land y\notin\operatorname{FVN_T}(u),\\
\forall_N z((A[y:=z])[x:=u]),&y\ne x\land y\in\operatorname{FVN_T}(u),
\end{cases}

(\forall_S ZA)[X:=Y]=
\begin{cases}
\forall_S ZA,&Z=X,\\
\forall_S Z(A[X:=Y]),&Z\ne X\land Z\ne Y,\\
\forall_S W((A[Z:=W])[X:=Y]),&Z\ne X\land Z=Y,
\end{cases}
